+// Sites (kitchens). Every location belongs to one site; a batch belongs to
+// the site of its location. Stock is seen per site; items, suppliers,
+// recipes and dishes are shared by all sites.
+import { AppError } from "../errors.js";
+
+/** The site used when a request names none. */
+export const DEFAULT_SITE = "main";
+
+/** Every site, in the order stored. */
+export function listSites(store) {
+  return [...(store.data.sites ?? [])];
+}
+
+/** One site, or AppError unknown_site. */
+export function getSite(store, id) {
+  const site = (store.data.sites ?? []).find((s) => s.id === id);
+  if (!site) throw new AppError("unknown_site", { id });
+  return site;
+}
+
+/** The site id of a location, or null for an unknown location. */
+export function siteOfLocation(store, locationId) {
+  return store.data.locations.find((l) => l.id === locationId)?.site ?? null;
+}
+
+/** Whether a location exists and belongs to `site` (any site when `site` is undefined). */
+export function locationInSite(store, locationId, site) {
+  const loc = store.data.locations.find((l) => l.id === locationId);
+  return Boolean(loc) && (site === undefined || loc.site === site);
+}
+
+/** Batches at `site` (all batches when `site` is undefined). */
+export function siteBatches(store, site) {
+  if (site === undefined) return store.data.batches;
+  const ids = new Set(store.data.locations.filter((l) => l.site === site).map((l) => l.id));
+  return store.data.batches.filter((b) => ids.has(b.location));
+}
